css:
[data-bz-section="site-footer"] .bz-block { padding-block: 0; }
[data-bz-section="site-footer"] .bz-block p { color: rgba(255,255,255,.66); font-size: 14px; line-height: 1.6; max-width: 46ch; }
[data-bz-section="site-footer"] .bz-nav--vertical { gap: 10px; }
[data-bz-section="site-footer"] .bz-navitem > a { font: 400 14px / 1.4 var(--font-body); color: rgba(255,255,255,.72); padding: 0; text-transform: none; letter-spacing: 0; }
[data-bz-section="site-footer"] .bz-navitem > a:hover { color: #fff; }
[data-bz-section="site-footer"] .bz-row[data-bz-node="ft-bottom"] { border-top: 1px solid rgba(255,255,255,.14); margin-top: 48px; padding-top: 22px; }
[data-bz-section="site-footer"] .bz-row[data-bz-node="ft-bottom"] p { font-size: 13px; margin: 0; }
[data-bz-section="site-footer"] .sl { margin-top: 22px; }
[data-bz-section="site-footer"] .bz-menu--vertical > .bz-nav { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
[data-bz-section="site-footer"] .bz-nav > .bz-navitem > .bz-navlabel { display: block; font: 700 13px / 1.3 var(--font-body); letter-spacing: .12em; text-transform: uppercase; color: #fff; margin: 0 0 14px; }
[data-bz-section="site-footer"] .bz-menu--vertical .bz-subnav { padding: 0; gap: 10px; }
@media (max-width: 640px) { [data-bz-section="site-footer"] .bz-menu--vertical > .bz-nav { grid-template-columns: minmax(0, 1fr); } [data-bz-section="site-footer"] .bz-subnav { min-width: 0; } }
